<div class="modal-backdrop app-modal-host" id="labTestQuickModal" aria-hidden="true"><div class="app-modal-dialog" data-size="lg" role="dialog" aria-modal="true" aria-labelledby="labTestQuickTitle"><form id="labTestQuickForm" class="app-modal-form" novalidate autocomplete="off"><div class="modal-header"><div class="modal-header-copy"><h2 id="labTestQuickTitle">Add Lab Test</h2><p>Create a Lab Test / Report charge without leaving Billing.</p></div><button class="modal-close" id="labTestQuickClose" type="button" aria-label="Close"><i data-lucide="x"></i></button></div><div class="modal-body"><div class="form-row"><div class="field col-3"><label>Lab Test Code</label><input id="quickLabTestCode" type="text" readonly></div><div class="field col-5"><label for="quickLabTestName" class="required">Lab Test / Report Name</label><input id="quickLabTestName" name="lab_test_name" type="text" maxlength="255" required></div><div class="field col-2"><label for="quickLabPrice" class="required">Price</label><input id="quickLabPrice" name="price" type="text" inputmode="decimal" value="0.00" required></div><div class="field col-2"><label>Status</label><select id="quickLabStatus" name="status"><option value="1">Active</option><option value="0">Inactive</option></select></div></div></div><div class="modal-footer"><div class="buttons"><button class="btn gray" id="labTestQuickCancel" type="button">Cancel</button><button class="btn btn-primary" id="labTestQuickSave" type="submit"><i data-lucide="save"></i> Save Lab Test</button></div></div></form></div></div>
<script>(function(window,document){'use strict';var modal=document.getElementById('labTestQuickModal'),form=document.getElementById('labTestQuickForm'),save=document.getElementById('labTestQuickSave'),onSaved=null,statusSelect=GlobalSelect.init('#quickLabStatus',{placeholder:'Status'});function openModal(){modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');setTimeout(function(){document.getElementById('quickLabTestName').focus();},50);if(window.lucide)window.lucide.createIcons();}function closeModal(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');onSaved=null;}async function openCreate(options){options=options||{};try{var response=await App.api('api/lab-tests.php?options=1'),data=response.data||{},actions=(data.allowed_actions||[]).map(Number);if(actions.indexOf(2)===-1){showToast('You do not have permission to create Lab Test.',{type:'danger',duration:3});return;}form.reset();document.getElementById('quickLabTestCode').value=data.next_lab_test_code||'';document.getElementById('quickLabPrice').value='0.00';form.status.value='1';if(statusSelect&&typeof statusSelect.sync==='function')statusSelect.sync();onSaved=typeof options.onSaved==='function'?options.onSaved:null;openModal();}catch(error){App.showError(error,'Unable to prepare Lab Test form.');}}form.addEventListener('submit',async function(event){event.preventDefault();Validation.clearForm(form);if(!Validation.validateForm(form))return;save.disabled=true;try{var data=new FormData(form);data.set('action','save');var response=await App.api('api/lab-tests.php',{method:'POST',body:data}),payload=response.data||{},cb=onSaved;showToast(response.message||'Lab Test saved successfully.',{type:'success',duration:2});closeModal();if(typeof cb==='function')cb(payload.record||payload);}catch(error){Validation.applyErrors(form,error.errors||{});App.showError(error,'Unable to save Lab Test.');}finally{save.disabled=false;}});document.getElementById('labTestQuickClose').addEventListener('click',closeModal);document.getElementById('labTestQuickCancel').addEventListener('click',closeModal);modal.addEventListener('click',function(e){if(e.target===modal)closeModal();});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&modal.classList.contains('open'))closeModal();});window.AppLabTestForm={openCreate:openCreate,close:closeModal};})(window,document);</script>